        visited = [False] * (len(graph) + 1)
        queue = deque(partition[0])
        visited[partition[0][0]] = True
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor in partition[1] and not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return all(visited[u] for u in partition[0])

    return bfs_check((U, V)) and bfs_check((V, U))

